 void followCamera(Location l){if(l.hasBearing()&&l.hasSpeed()&&l.getSpeed()>2.0){float next=l.getBearing();heading=headingSet?(heading+360+(float)((next-heading+540)%360-180)*.40f)%360:next;headingSet=true;}else if(!headingSet&&!routes.isEmpty()){double[] p=project(gp(l),routes.get(selected).points);if(p[1]<60){heading=(float)p[3];headingSet=true;}}map.setMapOrientation(-heading);map.setRotationX(0f);map.setScaleX(1f);map.setScaleY(1f);if(vector!=null&&vector.active()){vector.camera(gp(l),heading,tiltEnabled,true);return;}if(followEnabled){GeoPoint here=gp(l);double resolution=156543.03392*Math.cos(Math.toRadians(here.getLatitude()))/Math.pow(2,map.getZoomLevelDouble());double ahead=Math.max(40,Math.min(220,resolution*map.getHeight()*.23));GeoPoint center=here.destinationPoint(ahead,heading);map.getController().setCenter(center);}if(car!=null)car.setRotation(-heading);}
