 void restoreEvents(GeoPoint here){try{String raw=getSharedPreferences("road_cache",0).getString("snapshot","");if(raw.isEmpty())return;JSONObject snapshot=new JSONObject(raw);long age=System.currentTimeMillis()-snapshot.getLong("saved");if(age<0||age>3L*86400000)return;if(new GeoPoint(snapshot.getDouble("lat"),snapshot.getDouble("lon")).distanceToAsDouble(here)>7000)return;JSONArray data=snapshot.getJSONArray("events");ArrayList<Event> out=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject j=data.getJSONObject(i);Event e=new Event(j.getString("id"),j.getString("kind"),j.getString("label"),j.getString("source")+" · cache local",j.getDouble("lat"),j.getDouble("lon"));e.limit=j.optDouble("limit",0);e.direction=j.optDouble("dir",Double.NaN);out.add(e);}fixed=out;drawEvents();updateCoverage();}catch(Exception ignored){}}
 void saveEvents(GeoPoint here,ArrayList<Event> data){ArrayList<Event> snapshot=new ArrayList<>(data);pool.execute(()->{try{JSONArray out=new JSONArray();for(Event e:snapshot){if(e.expires!=Long.MAX_VALUE)continue;JSONObject j=new JSONObject().put("id",e.id).put("kind",e.kind).put("label",e.label).put("source",e.source).put("lat",e.p.getLatitude()).put("lon",e.p.getLongitude()).put("limit",Double.isFinite(e.limit)?e.limit:0);if(Double.isFinite(e.direction))j.put("dir",e.direction);out.put(j);if(out.length()>=15000)break;}JSONObject state=new JSONObject().put("saved",System.currentTimeMillis()).put("lat",here.getLatitude()).put("lon",here.getLongitude()).put("events",out);getSharedPreferences("road_cache",0).edit().putString("snapshot",state.toString()).apply();}catch(Exception ignored){}});}
 void refresh(){if(loc==null||fetching)return;GeoPoint p=gp(loc);if(catalogAt!=null&&catalogAt.distanceToAsDouble(p)<5000&&System.currentTimeMillis()-lastCatalog<3600000)return;fetching=true;pool.execute(()->{ArrayList<Event> f=new ArrayList<>();boolean ok=false;try{if(isBrazil(p)){JSONObject states=new JSONObject(get("https://raw.githubusercontent.com/Murkiriel/pardal/main/catalogo.json")).getJSONObject("ufs");Iterator<String> it=states.keys();while(it.hasNext()){String uf=it.next();if(uf.equals("BR"))continue;JSONObject u=states.getJSONObject(uf);JSONArray bb=u.optJSONArray("bbox");if(bb==null||p.getLatitude()<bb.getDouble(0)-.3||p.getLatitude()>bb.getDouble(2)+.3||p.getLongitude()<bb.getDouble(1)-.3||p.getLongitude()>bb.getDouble(3)+.3)continue;try{loadCatalog(uf,p,f);ok=true;}catch(Exception ignored){}}}}catch(Exception ignored){}
 try{loadSignals(p,f);ok=true;}catch(Exception ignored){}try{loadOsm(p,f);ok=true;}catch(Exception ignored){}if(isBrazil(p)){try{loadAntt(p,f);}catch(Exception ignored){}try{loadCariacica(p,f);}catch(Exception ignored){}}if(p.getLatitude()>21.7&&p.getLatitude()<25.5&&p.getLongitude()>119.5&&p.getLongitude()<122.2){try{loadTaiwan(p,f);}catch(Exception ignored){}}
 boolean done=ok;main.post(()->{fetching=false;if(done&&!f.isEmpty()){ArrayList<Event> combined=new ArrayList<>(f);fixed=combined;catalogAt=p;lastCatalog=System.currentTimeMillis();saveEvents(p,combined);}updateCoverage();drawEvents();});});}
 String trafficBase(int id){return "https://gis.vitoria.es.gov.br/arcgis/rest/services/Opendata/DadosAbertos/MapServer/"+id+"/query?where=1%3D1&returnGeometry=true&outSR=4326&resultRecordCount=1000&f=json&outFields=";}
 boolean trafficArea(GeoPoint p){return p.getLatitude()>-20.7&&p.getLatitude()<-19.9&&p.getLongitude()>-40.9&&p.getLongitude()<-39.95;}
 void refreshTraffic(){if(loc==null||fetchingTraffic)return;GeoPoint p=gp(loc);if(!trafficArea(p)&&!bcArea(p)&&!nycArea(p)){jams.clear();live.clear();jamFeedOk=false;alertFeedOk=false;trafficNewest=0;trafficStatus="Sem fonte de fluxo nesta região";updateCoverage();drawJams();drawEvents();return;}fetchingTraffic=true;trafficPool.execute(()->{ArrayList<Jam> j=new ArrayList<>();ArrayList<Event> l=new ArrayList<>();boolean jo=false,ao=false;String status="Fonte sem resposta";long now=System.currentTimeMillis();
 if(trafficArea(p)){try{JSONArray rows=trafficRows(26);status="Vitória/Waze: consulta OK, "+rows.length()+" registros recebidos";for(int i=0;i<rows.length();i++){try{JSONObject o=rows.getJSONObject(i),at=o.getJSONObject("attributes");long stamp=recordFreshness(at,now);if(stamp==0)continue;JSONArray paths=o.getJSONObject("geometry").getJSONArray("paths");for(int k=0;k<paths.length();k++){JSONArray path=paths.getJSONArray(k);Jam z=new Jam();z.id=at.optString("uuid")+":"+k;z.street=at.optString("street","");z.level=at.optInt("jam_level",0);z.speed=at.optDouble("jam_speedkmh",-1);z.delay=at.optDouble("delay",-1);z.observed=stamp;z.expires=stamp+900000;for(int n=0;n<path.length();n++){JSONArray pair=path.getJSONArray(n);z.points.add(new GeoPoint(pair.getDouble(1),pair.getDouble(0)));}if(z.points.size()>1&&z.level>0&&z.level<=5)j.add(z);}}catch(Exception ignored){}}jo=true;}catch(Exception ignored){status="Vitória/Waze: consulta indisponível";}
 try{JSONArray rows=trafficRows(25);for(int i=0;i<rows.length();i++){try{JSONObject o=rows.getJSONObject(i),at=o.getJSONObject("attributes"),g=o.getJSONObject("geometry");long stamp=recordFreshness(at,now);if(stamp==0)continue;String t=at.optString("alert_type").toUpperCase(Locale.ROOT),sub=at.optString("alert_subtype").toUpperCase(Locale.ROOT);String kind=sub.contains("POT_HOLE")?"buraco":sub.contains("CONSTRUCTION")?"obra":sub.contains("LANE_CLOSED")||t.contains("ROAD_CLOSED")?"interdicao":sub.contains("CAR_STOPPED")?"veiculo":sub.contains("FLOOD")?"alagamento":sub.contains("JAM")||t.equals("JAM")?"transito":t.contains("ACCIDENT")?"acidente":t.contains("CAMERA")?"radar":"perigo";String label=kind.equals("buraco")?"Buraco na via":kind.equals("obra")?"Obra na via":kind.equals("interdicao")?"Interdição reportada":kind.equals("veiculo")?"Veículo parado":kind.equals("alagamento")?"Alagamento reportado":kind.equals("transito")?"Trânsito intenso reportado":kind.equals("acidente")?"Acidente reportado":kind.equals("radar")?"Radar reportado":"Perigo reportado";Event e=new Event("waze"+at.optString("uuid"),kind,label,"Waze · Prefeitura de Vitória",g.getDouble("y"),g.getDouble("x"));e.expires=stamp+900000;l.add(e);}catch(Exception ignored){}}ao=true;}catch(Exception ignored){}}if(bcArea(p)){try{loadBC(p,l);ao=true;status="DriveBC: ocorrências rodoviárias";}catch(Exception ignored){}}if(nycArea(p)){try{loadNycSpeeds(p,l);ao=true;status="NYC DOT: medições de velocidade";}catch(Exception ignored){}}
 boolean jamOk=jo,alertsOk=ao;String detail=status;main.post(()->{fetchingTraffic=false;jamFeedOk=jamOk;alertFeedOk=alertsOk;trafficStatus=detail;if(jamOk)jams=j;else jams.removeIf(x->x.expires<System.currentTimeMillis());if(alertsOk)live=l;else live.removeIf(x->x.expires<System.currentTimeMillis());if(jamOk||alertsOk)trafficUpdated=System.currentTimeMillis();trafficNewest=0;for(Jam z:jams)trafficNewest=Math.max(trafficNewest,z.observed);updateCoverage();drawJams();drawEvents();});});}
 void updateCoverage(){long rad=fixed.stream().filter(e->e.kind.equals("radar")).count(),bumps=fixed.stream().filter(e->e.kind.equals("lombada")).count();String info=!jams.isEmpty()?jams.size()+" trechos recentes · "+(trafficNewest>0?"dados de "+Math.max(0,(System.currentTimeMillis()-trafficNewest)/60000)+" min atrás":"fonte regional"):jamFeedOk?"Fonte consultada · nenhum congestionamento recente retornado":alertFeedOk?"Dados regionais · fluxo não confirmado":"Trânsito: sem dados recentes confirmados";coverage.setText(rad+" radares · "+bumps+" lombadas\n"+info+(alertFeedOk?" · "+live.size()+" ocorrências":""));}
 void drawJams(){if(vector!=null&&vector.active()){vector.traffic();return;}map.getOverlays().removeAll(jamOverlays);jamOverlays.clear();long now=System.currentTimeMillis();for(Jam j:jams){if(j.expires<now)continue;Polyline line=new Polyline();line.setPoints(j.points);line.getOutlinePaint().setColor(j.level>=5?0xff991b1b:j.level>=4?0xffe53935:j.level==3?0xfff17b19:j.level==2?0xffedb829:0xff60aa76);line.getOutlinePaint().setStrokeWidth(dp(7));line.setTitle(j.street);line.setSnippet((j.level>=5?"Trânsito parado":j.level>=4?"Trânsito intenso":j.level==3?"Trânsito moderado":"Trânsito leve")+(j.speed>=0?" · "+Math.round(j.speed)+" km/h":"")+" · Waze / Vitória");line.setOnClickListener((o,m,point)->{toast(line.getTitle()+"\n"+line.getSnippet());return true;});map.getOverlays().add(line);jamOverlays.add(line);}map.invalidate();}

 long recordFreshness(JSONObject at,long now){long published=at.optLong("pubmillis",0),edited=at.optLong("last_edited_date",0);if(published<=0||published>now+60000)return 0;long fresh=published;if(edited>=published&&edited<=now+60000)fresh=edited;return now-fresh<=900000?fresh:0;}
 String jamLabel(Jam j){return j.level>=5?"Trânsito parado":j.level>=4?"Trânsito intenso":j.level==3?"Trânsito moderado":"Lentidão";}
 void warnJam(Route r,double[] pos,GeoPoint p){
 if(mode.equals("walk")||pos[1]>40){trafficBanner.setVisibility(View.GONE);return;}
 Jam closest=null;double nearest=Double.MAX_VALUE;
 for(Jam j:jams){if(j.expires<System.currentTimeMillis()||j.level<2)continue;
  for(int i=1;i<j.points.size();i++){GeoPoint a=j.points.get(i-1),b=j.points.get(i);double len=a.distanceToAsDouble(b);if(len<1||Math.min(a.distanceToAsDouble(p),b.distanceToAsDouble(p))>1800+len)continue;
   double bearing=(a.bearingTo(b)+360)%360;int n=Math.max(1,Math.min(48,(int)Math.ceil(len/30)));
   for(int k=0;k<=n;k++){GeoPoint sample=k==0?a:k==n?b:a.destinationPoint(len*k/n,bearing);if(sample.distanceToAsDouble(p)>1300)continue;double[] q=project(sample,r.points);double delta=q[0]-pos[0];if(q[1]>35||delta< -30||delta>1000||Math.abs((bearing-q[3]+540)%360-180)>70)continue;double d=Math.max(0,delta);if(d<nearest){nearest=d;closest=j;}}
  }
 }
 trafficBanner.setVisibility(View.VISIBLE);
 if(closest==null){trafficBanner.setText(jamFeedOk?"Trânsito: sem trecho recente retornado à frente":"Trânsito: cobertura não confirmada");return;}
 trafficBanner.setText(jamLabel(closest)+" · "+Math.round(nearest/10)*10+" m"+(closest.speed>=0?" · "+Math.round(closest.speed)+" km/h":"")+(closest.observed>0?" · "+Math.max(0,(System.currentTimeMillis()-closest.observed)/60000)+" min atrás":""));
 if(nearest<=700&&closest.level>=3&&System.currentTimeMillis()-lastWarn>4500&&warned.add("jam"+closest.id)){lastWarn=System.currentTimeMillis();alarm("transito",jamLabel(closest)+" a "+Math.round(nearest/10)*10+" metros");}
 }
 void trafficDetails(){String msg=trafficStatus+"\nÚltima consulta bem-sucedida: "+(trafficUpdated==0?"nenhuma":new java.text.SimpleDateFormat("HH:mm:ss",new Locale("pt","BR")).format(new Date(trafficUpdated)))+"\n"+jams.size()+" trechos recentes e "+live.size()+" registros regionais.\n\nA camada pública de Vitória não cobre todo o Waze, nem toda a Serra. Ausência de registros não significa trânsito livre. O mapa oficial é uma consulta separada e não fornece dados ao cálculo da rota.";new AlertDialog.Builder(this).setTitle("Trânsito ao vivo").setMessage(msg).setPositiveButton("Consultar Waze oficial",(d,i)->{if(driving&&loc!=null&&loc.hasSpeed()&&loc.getSpeed()>1.0){toast("Pare em local seguro antes de consultar o mapa.");return;}try{startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(loc==null?"https://www.waze.com/live-map/":"https://embed.waze.com/iframe?zoom=14&lat="+loc.getLatitude()+"&lon="+loc.getLongitude())));}catch(Exception e){toast("Não foi possível abrir o navegador.");}}).setNeutralButton("Atualizar fontes",(d,i)->refreshTraffic()).setNegativeButton("Fechar",null).show();}
 void loadCatalog(String uf,GeoPoint p,ArrayList<Event> out)throws Exception{String base="https://raw.githubusercontent.com/Murkiriel/pardal/main/estados/"+uf+"/";String[] rows=get(base+"radares.csv").split("\\r?\\n");if(rows.length<1)throw new IOException("Cadastro vazio");Map<String,Integer> cols=headerMap(rows[0]);if(!cols.containsKey("lat")||!cols.containsKey("lng")||!cols.containsKey("active"))throw new IOException("Formato do cadastro alterado");for(int i=1;i<rows.length;i++){try{String[] v=csvRow(rows[i]);double lat=Double.parseDouble(csv(v,cols,"lat")),lon=Double.parseDouble(csv(v,cols,"lng"));GeoPoint g=new GeoPoint(lat,lon);if(g.distanceToAsDouble(p)>65000)continue;String state=csv(v,cols,"active"),kind=csv(v,cols,"kind"),source=csv(v,cols,"source"),direction=csv(v,cols,"direction_deg");boolean active=state.equals("1")||state.equalsIgnoreCase("true");if(!active&&!uf.equals("ES"))continue;Event e=new Event("pardal"+lat+":"+lon+":"+direction,active?"radar":"historico",!active?"Radar histórico · operação não confirmada":kind.equals("RED_LIGHT")?"Radar de avanço de sinal":kind.equals("SECTION")?"Fiscalização por trecho":"Radar de velocidade","Pardal · "+source,lat,lon);try{e.limit=Double.parseDouble(csv(v,cols,"limit_kmh"));}catch(Exception ignored){}try{e.direction=Double.parseDouble(direction);}catch(Exception ignored){}mergeEvent(out,e);}catch(Exception ignored){}}
 try{String[] bumps=get(base+"lombadas.csv").split("\\r?\\n");Map<String,Integer> h=headerMap(bumps[0]);for(int i=1;i<bumps.length;i++){try{String[] v=csvRow(bumps[i]);double lat=Double.parseDouble(csv(v,h,"lat")),lon=Double.parseDouble(csv(v,h,"lng"));if(new GeoPoint(lat,lon).distanceToAsDouble(p)>25000)continue;mergeEvent(out,new Event("bump"+lat+":"+lon,"lombada","Lombada cadastrada","Pardal · OSM",lat,lon));}catch(Exception ignored){}}}catch(Exception ignored){}
 }
 Map<String,Integer> headerMap(String line){String[] a=csvRow(line.replace("\uFEFF",""));Map<String,Integer> out=new HashMap<>();for(int i=0;i<a.length;i++)out.put(norm(a[i]),i);return out;}
 void drawEvents(){if(vector!=null&&vector.active()){vector.events();return;}map.getOverlays().removeAll(eventOverlays);eventOverlays.clear();ArrayList<Event> all=new ArrayList<>(fixed);all.addAll(live);GeoPoint here=loc==null?null:gp(loc);for(Event e:all){if(here==null||e.p.distanceToAsDouble(here)>12000||e.expires<System.currentTimeMillis())continue;if(e.kind.equals("lombada")&&map.getZoomLevelDouble()<14)continue;if(eventOverlays.size()>1600&&!e.kind.equals("radar")&&!e.kind.equals("semaforo"))continue;Marker m=new Marker(map);m.setPosition(e.p);m.setTitle(e.label+(e.limit>0?" · "+(int)e.limit+" km/h":""));m.setSnippet(e.source);m.setIcon(e.kind.equals("radar")?(e.limit>0?symbol(String.valueOf((int)e.limit),0xffb91c1c):mapIcon(e.label.contains("sinal")?"redcamera":"camera",0xffb91c1c)):e.kind.equals("semaforo")?trafficIcon():mapIcon(e.kind.equals("lombada")?"bump":e.kind.equals("historico")?"camera":"hazard",e.kind.equals("historico")?0xff64748b:0xffd97706));m.setAnchor(Marker.ANCHOR_CENTER,Marker.ANCHOR_CENTER);map.getOverlays().add(m);eventOverlays.add(m);}map.invalidate();}

 void themeDialog(){String[] labels={"Automático","Claro","Escuro"};new AlertDialog.Builder(this).setTitle("Tema do Rota Única").setSingleChoiceItems(labels,theme.equals("dark")?2:theme.equals("light")?1:0,(d,i)->{theme=i==2?"dark":i==1?"light":"auto";getPreferences(0).edit().putString("theme",theme).apply();applyTheme();d.dismiss();}).setNegativeButton("Fechar",null).show();}
