 void showUpcoming(GeoPoint p,Route r,double[] pos){Event radar=null,signal=null;double rd=1001,sd=501;for(Event e:fixed){if(e.p.distanceToAsDouble(p)>1100)continue;if(!e.kind.equals("radar")&&!e.kind.equals("semaforo"))continue;double[] z=project(e.p,r.points);double d=z[0]-pos[0];if(z[1]>40||d<(e.kind.equals("semaforo")?-12:0))continue;d=Math.max(0,d);if(!Double.isNaN(e.direction)&&Math.abs((z[3]-e.direction+540)%360-180)>65)continue;if(e.kind.equals("radar")&&d<rd){radar=e;rd=d;}if(e.kind.equals("semaforo")&&d<sd){signal=e;sd=d;}}radarBanner.setVisibility(radar==null||mode.equals("walk")?View.GONE:View.VISIBLE);if(radar!=null)radarBanner.setText(radar.label+" · "+Math.round(rd)+" m"+(radar.limit>0?" · "+(int)radar.limit+" km/h":""));observeDelay(p,r,pos,signal,sd);if(signal==null||pos[1]>40||mode.equals("walk")){clearSignalWait();return;}String key=delayBucket(signal,project(signal.p,r.points)[3]);if(!signal.id.equals(waitSignalId)){if(waitSignalPoint==null||waitSignalPoint.distanceToAsDouble(signal.p)>25)waitStart=0;waitSignalId=signal.id;waitSignalPoint=signal.p;}if(!key.equals(currentDelayKey)){currentDelayKey=key;currentDelays=readDelays(key);}signalDistance=sd;signalStopCandidate=loc!=null&&loc.hasSpeed()&&loc.getSpeed()<=(waitStart>0?1.3:.8)&&loc.hasAccuracy()&&loc.getAccuracy()<=35&&sd<=85;if(signalStopCandidate){if(waitStart==0)waitStart=SystemClock.elapsedRealtime();}else waitStart=0;renderSignalWait();}
