 void renderSignalWait(){if(signalBanner==null)return;if(!driving||waitSignalId==null||loc==null||SystemClock.elapsedRealtimeNanos()-loc.getElapsedRealtimeNanos()>15000000000L){clearSignalWait();return;}signalBanner.setVisibility(View.VISIBLE);long seconds=waitStart>0?(SystemClock.elapsedRealtime()-waitStart)/1000:0;String text="Semáforo a "+Math.round(signalDistance)+" m · fase não informada";if(SystemClock.elapsedRealtimeNanos()-loc.getElapsedRealtimeNanos()>6000000000L){signalBanner.setText(text+"\nAguardando GPS");return;}if(signalStopCandidate&&seconds>=3)text+="\nEspera decorrida: "+String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60);if(signalStopCandidate&&seconds>=3){String estimate=estimateDelay(currentDelays,seconds);if(estimate!=null)text+="\nEspera restante estimada: "+estimate+" · histórico local";}signalBanner.setText(text);}
 String delayBucket(Event signal,double bearing){Calendar c=Calendar.getInstance();int day=c.get(Calendar.DAY_OF_WEEK),hour=c.get(Calendar.HOUR_OF_DAY);int sector=(int)Math.floor((bearing+22.5)/45)%8;return signal.id+"_"+sector+"_"+((day==Calendar.SATURDAY||day==Calendar.SUNDAY)?"fim":"util")+"_"+hour+"_"+mode;}
